param (
    [string]$TranscriptPath = "doc\prompts\16. Minimalist Dark Theme Interface and Hosted Web Server\transcript_full.jsonl",
    [string]$OutputPath = "doc\prompts\16. Minimalist Dark Theme Interface and Hosted Web Server\conversation.md",
    [string]$PendingResponsePath = ""
)

if (-not (Test-Path $TranscriptPath)) {
    Write-Error "Transcript not found: $TranscriptPath"
    exit 1
}

$lines = [System.IO.File]::ReadAllLines($TranscriptPath, [System.Text.Encoding]::UTF8)

$steps = [System.Collections.Generic.List[PSCustomObject]]::new()
foreach ($l in $lines) {
    if ([string]::IsNullOrWhiteSpace($l)) { continue }
    try {
        $step = $l | ConvertFrom-Json
        $steps.Add($step)
    } catch {
        Write-Warning "Failed to parse json line: $_"
    }
}

$sb = [System.Text.StringBuilder]::new()
[void]$sb.AppendLine("# Conversation: Minimalist Dark Theme Interface and Hosted Web Server")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("- **Conversation ID**: `12d2caa0-dc44-4a5d-a2b7-a78b5731a28e`")
[void]$sb.AppendLine("- **Session Folder**: `doc/prompts/16. Minimalist Dark Theme Interface and Hosted Web Server/`")
[void]$sb.AppendLine("- **Timestamp**: `2026-11-13T22:07:57+06:00`")
[void]$sb.AppendLine("- **Model**: `Gemini 3.8 Flash`")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("---")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("## Table of Contents")
[void]$sb.AppendLine("- [Step-by-Step Trajectory](#step-by-step-trajectory)")

foreach ($step in $steps) {
    $idx = $step.step_index
    $src = $step.source
    $type = $step.type
    $anchor = ("step-$idx-$src-$type").ToLower().Replace('_', '-').Replace(' ', '-').Replace('/', '')
    [void]$sb.AppendLine("  - [Step $idx`: $src / $type](#$anchor)")
}

if ($PendingResponsePath -and (Test-Path $PendingResponsePath)) {
    [void]$sb.AppendLine("- [Pending Final Response (Pre-Commit)](#pending-final-response-pre-commit)")
}

[void]$sb.AppendLine("")
[void]$sb.AppendLine("---")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("## Step-by-Step Trajectory")
[void]$sb.AppendLine("")

foreach ($step in $steps) {
    $idx = $step.step_index
    $src = $step.source
    $type = $step.type
    $createdAt = $step.created_at

    [void]$sb.AppendLine("### Step $idx`: $src / $type")
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("- **Created At**: `$createdAt`")
    [void]$sb.AppendLine("- **Source**: `$src`")
    [void]$sb.AppendLine("- **Type**: `$type`")
    [void]$sb.AppendLine("")

    if ($step.thinking) {
        [void]$sb.AppendLine("#### Thinking")
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine($step.thinking)
        [void]$sb.AppendLine("")
    }

    if ($step.content) {
        [void]$sb.AppendLine("#### Content")
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine($step.content)
        [void]$sb.AppendLine("")
    }

    if ($step.tool_calls -and $step.tool_calls.Count -gt 0) {
        [void]$sb.AppendLine("#### Tool Calls")
        [void]$sb.AppendLine("")
        foreach ($tc in $step.tool_calls) {
            $toolName = if ($tc.function) { $tc.function.name } elseif ($tc.name) { $tc.name } else { "Tool" }
            $argsJson = if ($tc.function -and $tc.function.arguments) {
                if ($tc.function.arguments -is [string]) { $tc.function.arguments } else { $tc.function.arguments | ConvertTo-Json -Depth 10 }
            } elseif ($tc.arguments) {
                if ($tc.arguments -is [string]) { $tc.arguments } else { $tc.arguments | ConvertTo-Json -Depth 10 }
            } else { "{}" }

            [void]$sb.AppendLine('```json')
            [void]$sb.AppendLine("// Tool: $toolName")
            [void]$sb.AppendLine($argsJson)
            [void]$sb.AppendLine('```')
            [void]$sb.AppendLine("")
        }
    }

    [void]$sb.AppendLine("---")
    [void]$sb.AppendLine("")
}

if ($PendingResponsePath -and (Test-Path $PendingResponsePath)) {
    $pendingText = [System.IO.File]::ReadAllText($PendingResponsePath, [System.Text.Encoding]::UTF8)
    [void]$sb.AppendLine("## Pending Final Response (Pre-Commit)")
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("> *Note: This section captures the final turn response before runtime writes it to transcript_full.jsonl. It will be replaced verbatim on the next archive sync.*")
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine($pendingText)
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("---")
}

[System.IO.File]::WriteAllText($OutputPath, $sb.ToString(), [System.Text.Encoding]::UTF8)
Write-Host "Generated $OutputPath with $($steps.Count) steps."

