  const src = step.source;
  const type = step.type;
  const createdAt = step.created_at;

  out.push(`### Step ${idx}: ${src} / ${type}`);
  out.push('');
  out.push(`- **Created At**: \`${createdAt}\``);
  out.push(`- **Source**: \`${src}\``);
  out.push(`- **Type**: \`${type}\``);
  out.push('');

  if (step.thinking) {
    out.push('#### Thinking');
    out.push('');
    out.push(step.thinking);
    out.push('');
  }

  if (step.content) {
    out.push('#### Content');
    out.push('');
    out.push(step.content);
    out.push('');
  }

  if (step.tool_calls && step.tool_calls.length > 0) {
    out.push('#### Tool Calls');
    out.push('');
    for (const tc of step.tool_calls) {
      const toolName = tc.function?.name || tc.name || 'Tool';
      let argsJson = '{}';
      if (tc.function && tc.function.arguments) {
        argsJson = typeof tc.function.arguments === 'string'
          ? tc.function.arguments
          : JSON.stringify(tc.function.arguments, null, 2);
      } else if (tc.arguments) {
        argsJson = typeof tc.arguments === 'string'
          ? tc.arguments
          : JSON.stringify(tc.arguments, null, 2);
      }
      out.push('```json');
      out.push(`// Tool: ${toolName}`);
      out.push(argsJson);
      out.push('```');
      out.push('');
    }
  }

  out.push('---');
  out.push('');
}

if (fs.existsSync(pendingPath)) {
  const pendingText = fs.readFileSync(pendingPath, 'utf8');
  out.push('## Pending Final Response (Pre-Commit)');
  out.push('');
  out.push('> *Note: This section captures the final turn response before runtime writes it to transcript_full.jsonl. It will be replaced verbatim on the next archive sync.*');
  out.push('');
  out.push(pendingText);
  out.push('');
  out.push('---');
}

fs.writeFileSync(outputPath, out.join('\n'), 'utf8');
console.log(`Generated ${outputPath} with ${steps.length} steps.`);

