function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function loadFiles() {
  fetch('/api/files')
    .then(function (res) {
      if (!res.ok) throw new Error('API returned status: ' + res.status);
      return res.json();
    })
    .then(function (data) {
      var summary = document.getElementById('storageSummary');
      var fill = document.getElementById('meterBarFill');
      if (summary && data.usedFormatted && data.totalFormatted) {
        summary.textContent = data.usedFormatted + ' / ' + data.totalFormatted + ' (' + data.usedPercent + '% Used)';
      }
      if (fill && typeof data.usedPercent !== 'undefined') {
        fill.style.width = data.usedPercent + '%';
      }

      var tbody = document.getElementById('fileTableBody');
      if (!tbody) return;
      tbody.innerHTML = '';

      if (!data.files || data.files.length === 0) {
        tbody.innerHTML = '<tr><td colspan="3" style="text-align: center; color: var(--text-dim); padding: 24px;">No files found on storage. Upload one above!</td></tr>';
        return;
      }

      data.files.forEach(function (item) {
        var tr = document.createElement('tr');

        var nameTd = document.createElement('td');
        nameTd.innerHTML = '<strong>📄 ' + escapeHtml(item.name) + '</strong> <span class="tag-folder">' + escapeHtml(item.dir) + '</span>';

        var sizeTd = document.createElement('td');
        sizeTd.textContent = item.sizeFormatted || fmtBytes(item.size);

        var actTd = document.createElement('td');
        actTd.style.textAlign = 'right';

        var dlBtn = document.createElement('a');
        dlBtn.href = '/get?file=' + encodeURIComponent(item.path);
        dlBtn.className = 'btn-action btn-dl';
        dlBtn.textContent = 'Download';
        actTd.appendChild(dlBtn);

        if (item.isProtected) {
          var protSpan = document.createElement('span');
          protSpan.className = 'badge-protected';
          protSpan.textContent = '🔒 Protected';
          actTd.appendChild(protSpan);
        } else {
          var delBtn = document.createElement('a');
          delBtn.href = '/delete?file=' + encodeURIComponent(item.path);
          delBtn.className = 'btn-action btn-del';
          delBtn.textContent = 'Delete';
          delBtn.onclick = function () {
            return confirm('Delete ' + item.name + '?');
          };
          actTd.appendChild(delBtn);
        }

        tr.appendChild(nameTd);
        tr.appendChild(sizeTd);
        tr.appendChild(actTd);
        tbody.appendChild(tr);
      });
    })
    .catch(function (err) {
      // Keep static preview rows if running in standalone/offline file:/// mode
      console.log('Running in local/offline preview mode:', err.message);
    });
}

