           formatBytes(total) + " (" + String(usedPercent, 1) +
           "% Used)</span>";
  meter += "</div>";
  meter += "<div class='progress-bar-bg'><div class='progress-bar-fill' "
           "style='width: " +
           String(usedPercent, 1) + "%;'></div></div>";
  meter += "</div>";
  server.sendContent(meter);

  // Upload Form section with real-time transfer speed & progress indicators
  String uploadBox = "<div class='upload-box'>";
