  uploadBox += "<div class='progress-bar-bg'><div id='progressBarFill' "
               "class='progress-bar-fill' style='width: 0%;'></div></div>";
  uploadBox +=
      "<div class='progress-info' style='margin-top: 10px; margin-bottom: 0;'>";
  uploadBox += "<span id='bytesDisplay' style='color: var(--text-muted);'>0 B "
               "/ 0 B</span>";
  uploadBox += "<span id='speedDisplay' class='speed-badge'>⚡ 0 KB/s</span>";
  uploadBox +=
      "<span id='etaDisplay' class='eta-badge'>⏱ Calculating...</span>";
  uploadBox += "</div>";
  uploadBox += "</div>";
  uploadBox += "</div>";
  server.sendContent(uploadBox);

  // File Table section
  String tableStart = "<div class='table-card'><table>";
  tableStart += "<tr><th>File Name & Location</th><th>Size</th><th "
                "style='text-align: right;'>Actions</th></tr>";
  server.sendContent(tableStart);

  std::vector<StorageItem> items;
