  collectFilesRecursively(root, items);
  root.close();

  for (const auto &item : items) {
    int lastSlash = item.path.lastIndexOf('/');
    String dirName = (lastSlash > 0) ? item.path.substring(0, lastSlash) : "/";
    String baseName =
        (lastSlash >= 0) ? item.path.substring(lastSlash + 1) : item.path;

    String row = "<tr>";
    row += "<td><strong>📄 " + baseName +
           "</strong> <span class='tag-folder'>" + dirName + "</span></td>";
    row += "<td>" + formatBytes(item.size) + "</td>";
    row += "<td style='text-align: right;'>";
    row += "<a href='/get?file=" + item.path +
           "' class='btn-action btn-dl'>Download</a>";

    if (item.isProtected) {
      row += "<span class='badge-protected'>🔒 Protected</span>";
    } else {
      row += "<a href='/delete?file=" + item.path +
             "' class='btn-action btn-del' onclick=\"return confirm('Delete " +
             baseName + "?');\">Delete</a>";
    }

    row += "</td></tr>";
    server.sendContent(row);
  }

  if (items.empty()) {
    server.sendContent("<tr><td colspan='3' style='text-align: center; color: "
                       "#64748b; padding: 24px;'>No files found on storage. "
                       "Upload one above!</td></tr>");
  }

  server.sendContent("</table></div>");
  server.sendContent(FPSTR(NAS_PAGE_FOOTER));
}

