// --- Auto Page Reload & File Sync Timer (10 Seconds) ---
var countdown = 10;
var isUploading = false;

function tickAutoSync() {
  var cdElem = document.getElementById('countdown');
  if (isUploading) {
    if (cdElem) cdElem.textContent = '--';
    return;
  }
  countdown--;
  if (countdown <= 0) {
    countdown = 10;
    loadFiles();
  }
  if (cdElem) cdElem.textContent = countdown;
}

var autoSyncTimer = setInterval(tickAutoSync, 1000);

var syncBadge = document.getElementById('syncIndicator');
if (syncBadge) {
  syncBadge.onclick = function () {
    if (!isUploading) {
      countdown = 10;
      var cdElem = document.getElementById('countdown');
