void handleApiFiles() {
  uint64_t total = SD.totalBytes();
  uint64_t used = SD.usedBytes();
  float usedPercent =
      (total > 0) ? ((float)used / (float)total) * 100.0f : 0.0f;

  std::vector<StorageItem> items;
  File root = SD.open("/");
  collectFilesRecursively(root, items);
  root.close();

